function openModal(kind,id,extra){const modal=$('#modal');let contents='';if(kind==='new-record')contents=recordForm();if(kind==='edit-record')contents=recordForm(id);if(kind==='view-record')contents=recordDetail(id);if(kind==='new-member')contents=memberForm();if(kind==='edit-member')contents=memberForm(id);if(kind==='view-member')contents=memberDetail(id);if(kind==='new-tx')contents=txForm(null,extra);if(kind==='edit-tx')contents=txForm(id);if(kind==='view-tx')contents=txDetail(id);if(kind==='categories')contents=categoryEditor(id);if(kind==='category-form')contents=categoryForm(id,extra?.group|| (id==='record'?'personal':'expense'),extra?.catId);if(kind==='quick-add')contents=`${heading('Bạn muốn thêm gì?')}<div class="list"><button class="setting-item" data-action="new-record"><strong>▤ Hồ sơ & giấy tờ</strong><span class="right-arrow">›</span></button><button class="setting-item" data-action="new-member"><strong>♧ Thành viên</strong><span class="right-arrow">›</span></button><button class="setting-item" data-action="new-income"><strong>↗ Khoản thu</strong><span class="right-arrow">›</span></button><button class="setting-item" data-action="new-expense"><strong>↘ Khoản chi</strong><span class="right-arrow">›</span></button></div>`;if(kind==='restore')contents=`${heading('Khôi phục sao lưu')}<p class="subtext">File sao lưu sẽ <strong>thay thế toàn bộ dữ liệu hiện tại</strong> trên thiết bị. Hãy sao lưu dữ liệu hiện tại trước.</p><form id="editorForm" data-kind="restore">${field('Mật khẩu của bản sao lưu <span class="req">*</span>','password','','password','required autocomplete="off"')}<div class="modal-footer"><button type="button" class="secondary-btn" data-action="close-modal">Hủy</button><button type="submit" class="danger-btn">Khôi phục dữ liệu</button></div></form>`;if(kind==='change-password')contents=`${heading('Thay đổi mật khẩu')}<p class="subtext">Ứng dụng sẽ mã hóa lại toàn bộ hồ sơ và tệp đính kèm. Nên tạo bản sao lưu trước.</p><form id="editorForm" data-kind="change-password">${field('Mật khẩu đang dùng','old','','password','required autocomplete="current-password"')}${field('Mật khẩu mới (ít nhất 8 ký tự)','password','','password','required minlength="8" autocomplete="new-password"')}${field('Xác nhận mật khẩu mới','confirm','','password','required minlength="8" autocomplete="new-password"')}<div class="modal-footer"><button type="button" class="secondary-btn" data-action="close-modal">Hủy</button><button type="submit" class="primary-btn">Đổi mật khẩu</button></div></form>`;if(!contents)return;$('#modalBody').innerHTML=contents;if(!modal.open)modal.showModal();$('#modalBody').scrollTop=0;if(kind==='new-record'||kind==='edit-record')setRecordCommonLabels($('#f_module').value);}
function closeModal(){closeAttachmentPreview();const m=$('#modal');if(m.open)m.close();activeEdit=null;backupPending=null;}
async function storeFiles(input){const files=[...input?.files||[]];for(const f of files)if(f.size>MAX_FILE_BYTES)throw new Error('File '+f.name+' vượt 15 MB.');const added=[];try{for(const f of files){const id=uid();const enc=await encryptBytes(await f.arrayBuffer(),vaultKey);await dbPut('files',id,enc);added.push({id,name:f.name,size:f.size,mime:f.type||'application/octet-stream'});}return added;}catch(e){for(const f of added)await dbDelete('files',f.id).catch(()=>{});throw e;}}
async function removeFiles(ids){for(const id of ids)await dbDelete('files',id);}
async function downloadAttachment(id){const row=await dbGet('files',id);if(!row){toast('Không tìm thấy tệp đính kèm.');return;}const ref=[...state.records,...state.transactions].flatMap(x=>x.attachments||[]).find(a=>a.id===id);if(!ref){toast('Tệp không còn trong danh mục.');return;}try{const data=await decryptBytes(row,vaultKey);saveBlob(new Blob([data],{type:ref.mime||'application/octet-stream'}),ref.name||'tep-dinh-kem');}catch(e){toast('Không thể giải mã tệp.');}}
// V3.2: local-only attachment preview. Do not render active HTML/SVG or use external viewers.
let previewEpoch=0, previewURL='';
function attachmentPreviewKind(bytes,name,mime){
  const b=new Uint8Array(bytes), at=(i,...v)=>v.every((x,j)=>b[i+j]===x), str=(i,v)=>at(i,...Array.from(v,x=>x.charCodeAt(0)));
  if(at(0,255,216,255))return ['image','image/jpeg'];
  if(at(0,137,80,78,71,13,10,26,10))return ['image','image/png'];
  if(str(0,'GIF87a')||str(0,'GIF89a'))return ['image','image/gif'];
  if(str(0,'RIFF')&&str(8,'WEBP'))return ['image','image/webp'];
  if(str(0,'BM'))return ['image','image/bmp'];
  if(str(0,'%PDF-'))return ['pdf','application/pdf'];
  if(/\.txt$/i.test(name||'')||mime==='text/plain')return ['text','text/plain'];
  return ['unsupported','application/octet-stream'];
}
function clearAttachmentPreview(){previewEpoch++;if(previewURL){URL.revokeObjectURL(previewURL);previewURL='';}const d=$('#attachmentPreview');if(d){d.querySelector('.preview-content').replaceChildren();d.querySelector('.preview-title').textContent='';d.querySelector('.preview-download').onclick=null;}}
function closeAttachmentPreview(){const d=$('#attachmentPreview');clearAttachmentPreview();if(d?.open)d.close();}
function attachmentPreviewDialog(){let d=$('#attachmentPreview');if(d)return d;d=document.createElement('dialog');d.id='attachmentPreview';d.setAttribute('aria-labelledby','previewHeading');d.innerHTML='<header class="preview-head"><div><h2 id="previewHeading">Xem tệp đính kèm</h2><div class="preview-title"></div></div><button type="button" class="close-btn preview-close" aria-label="Đóng tệp">×</button></header><div class="preview-content"></div><footer class="preview-footer"><button type="button" class="secondary-btn preview-back">Đóng</button><button type="button" class="primary-btn preview-download">Tải tệp</button></footer>';document.body.appendChild(d);d.querySelector('.preview-close').onclick=closeAttachmentPreview;d.querySelector('.preview-back').onclick=closeAttachmentPreview;d.addEventListener('cancel',e=>{e.preventDefault();closeAttachmentPreview();});d.addEventListener('close',()=>{if(!d.open)clearAttachmentPreview();});return d;}
async function previewAttachment(id){
  if(!state||!vaultKey)return;
  const ref=[...state.records,...state.transactions].flatMap(x=>x.attachments||[]).find(a=>a.id===id);
  if(!ref){toast('Không tìm thấy tệp đính kèm.');return;}
  const d=attachmentPreviewDialog();clearAttachmentPreview();const epoch=previewEpoch,key=vaultKey,session=state;
  const live=()=>epoch===previewEpoch&&key===vaultKey&&session===state&&d.open;
  const body=d.querySelector('.preview-content'),button=d.querySelector('.preview-download');
  d.querySelector('.preview-title').textContent=ref.name||'Tệp đính kèm';body.textContent='Đang giải mã tệp…';button.disabled=true;if(!d.open)d.showModal();
  try{const row=await dbGet('files',id);if(!live())return;if(!row)throw new Error('Tệp không tồn tại trên thiết bị.');const data=await decryptBytes(row,key);if(!live())return;
    const [kind,mime]=attachmentPreviewKind(data,ref.name,ref.mime);body.replaceChildren();button.disabled=false;button.onclick=()=>{if(live())saveBlob(new Blob([data],{type:ref.mime||'application/octet-stream'}),ref.name||'tep-dinh-kem');};
    if(kind==='image'){previewURL=URL.createObjectURL(new Blob([data],{type:mime}));const image=document.createElement('img');image.alt='Ảnh đính kèm';image.src=previewURL;image.onerror=()=>{if(live())body.textContent='Trình duyệt không đọc được ảnh này. Hãy chọn Tải tệp.';};body.appendChild(image);}
    else if(kind==='pdf'){previewURL=URL.createObjectURL(new Blob([data],{type:mime}));const hint=document.createElement('p');hint.className='preview-note';hint.textContent='Nếu PDF không hiển thị trên thiết bị này, hãy chọn Tải tệp để mở bằng trình đọc PDF.';const frame=document.createElement('iframe');frame.title='Tài liệu PDF';frame.src=previewURL;frame.referrerPolicy='no-referrer';body.append(hint,frame);}
    else if(kind==='text'){const pre=document.createElement('pre');const limit=1024*1024;pre.textContent=new TextDecoder().decode(new Uint8Array(data).subarray(0,limit))+(data.byteLength>limit?'\n… Chỉ hiển thị 1 MB đầu. Tải tệp để đọc đầy đủ.':'');body.appendChild(pre);}
    else body.textContent='Loại tệp này chưa hỗ trợ xem trực tiếp. Chọn Tải tệp để mở bằng ứng dụng phù hợp (Word, Excel, v.v.).';
  }catch(e){if(live()){body.textContent='Không thể mở tệp: '+e.message;button.disabled=true;}}
}
function saveBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}
async function saveEditor(form){const data=new FormData(form),kind=form.dataset.kind;const v=n=>String(data.get(n)||'').trim();const n=v=>Number(data.get(v));if(kind==='member'){const name=v('name');if(!name)throw new Error('Cần nhập họ tên.');const member={id:activeEdit.id||uid(),name,relation:v('relation'),birth:v('birth'),phone:v('phone'),notes:v('notes'),createdAt:state.members.find(m=>m.id===activeEdit.id)?.createdAt||new Date().toISOString()};const i=state.members.findIndex(m=>m.id===member.id);if(i<0)state.members.push(member);else state.members[i]=member;await persist();closeModal();render();toast('Đã lưu thành viên.');return;}
  if(kind==='record'||kind==='transaction'){
    const isDoc=kind==='record';const original=isDoc?getRecord(activeEdit.id):state.transactions.find(x=>x.id===activeEdit.id);const fileInput=form.querySelector('input[type=file]');const added=await storeFiles(fileInput);let newItem;
    try{
      if(isDoc){const module=v('module'),typeId=v('typeId');if(!state.categories.records[module]?.some(c=>c.id===typeId))throw new Error('Loại hồ sơ chưa hợp lệ.');if(!v('title'))throw new Error('Hãy nhập tên hồ sơ.');newItem={id:activeEdit.id||uid(),module,typeId,owner:v('owner')||'family',title:v('title'),number:v('number'),issuer:v('issuer'),issuedAt:v('issuedAt'),expiresAt:v('expiresAt'),notes:v('notes'),details:collectRecordDetails(form,module,typeId,original),attachments:[...(original?.attachments||[]).filter(a=>!activeEdit.remove.has(a.id)),...added],createdAt:original?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(newItem.issuedAt&&newItem.expiresAt&&newItem.expiresAt<newItem.issuedAt)throw new Error('Ngày hết hạn không được trước ngày cấp.');}
      else {const type=v('type'),categoryId=v('categoryId');if(!state.categories.transactions[type]?.some(c=>c.id===categoryId))throw new Error('Hạng mục thu – chi không hợp lệ.');if(!Number.isSafeInteger(n('amount'))||n('amount')<=0)throw new Error('Số tiền phải là số nguyên dương hợp lệ.');newItem={id:activeEdit.id||uid(),type,categoryId,amount:n('amount'),date:v('date'),owner:v('owner')||'family',payment:v('payment'),note:v('note'),attachments:[...(original?.attachments||[]).filter(a=>!activeEdit.remove.has(a.id)),...added],createdAt:original?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(!newItem.date)throw new Error('Cần chọn ngày giao dịch.');}
      if(newItem.owner!=='family'&&!state.members.some(m=>m.id===newItem.owner))throw new Error('Thành viên không tồn tại.');
      const array=isDoc?state.records:state.transactions,i=array.findIndex(x=>x.id===newItem.id);if(i<0)array.push(newItem);else array[i]=newItem;await persist();await removeFiles([...activeEdit.remove]);closeModal();render();toast(isDoc?'Đã lưu hồ sơ.':'Đã lưu khoản thu – chi.');
    }catch(e){await removeFiles(added.map(a=>a.id)).catch(()=>{});throw e;}
    return;
  }
  if(kind==='category'){const {categoryKind,group,id}=activeEdit;const targetGroup=id?group:v('group');const groups=categoryKind==='record'?state.categories.records:state.categories.transactions;const arr=groups[targetGroup];if(!arr)throw new Error('Nhóm danh mục không hợp lệ.');const name=v('name');if(!name)throw new Error('Cần nhập tên loại.');if(arr.some(c=>c.id!==id&&norm(c.name)===norm(name)))throw new Error('Tên loại đã có trong nhóm.');const customFields=categoryKind==='record'?parseCustomFieldLines(v('customFields'),id?(arr.find(c=>c.id===id)?.fields||[]):[]):null;
    if(id&&customFields){const old=arr.find(c=>c.id===id);const removed=(old?.fields||[]).filter(f=>!customFields.some(next=>next.key===f.key));if(removed.some(f=>state.records.some(r=>r.module===targetGroup&&r.typeId===id&&String(r.details?.[f.key]??'').trim())))throw new Error('Trường đang có dữ liệu trong hồ sơ. Không thể xóa; hãy giữ trường này hoặc sửa nội dung hồ sơ trước.');}
    if(id){const x=arr.find(c=>c.id===id);if(!x)throw new Error('Danh mục không tồn tại.');x.name=name;if(customFields)x.fields=customFields;}else arr.push({id:uid(),name,system:false,...(customFields?{fields:customFields}:{})});await persist();openModal('categories',categoryKind);render();toast('Đã lưu danh mục.');return;}
  if(kind==='restore'){const pass=v('password');if(!backupPending)throw new Error('Chưa chọn file sao lưu.');await restoreBackup(backupPending,pass);closeModal();render();toast('Khôi phục thành công.');return;}
  if(kind==='change-password'){if(v('password').length<8||v('password')!==v('confirm'))throw new Error('Mật khẩu mới không khớp hoặc quá ngắn.');await changePassword(v('old'),v('password'));closeModal();render();toast('Đã thay mật khẩu và mã hóa lại dữ liệu.');return;}
}
async function deleteRecord(id){const r=getRecord(id);if(!r)return;if(!confirm(`Xóa hồ sơ “${r.title}” và mọi tệp đính kèm?`))return;state.records=state.records.filter(x=>x.id!==id);await persist();await removeFiles((r.attachments||[]).map(a=>a.id));closeModal();render();toast('Đã xóa hồ sơ.');}
async function deleteTx(id){const t=state.transactions.find(x=>x.id===id);if(!t)return;if(!confirm('Xóa giao dịch và các chứng từ đính kèm?'))return;state.transactions=state.transactions.filter(x=>x.id!==id);await persist();await removeFiles((t.attachments||[]).map(a=>a.id));closeModal();render();toast('Đã xóa giao dịch.');}
async function deleteMember(id){const m=state.members.find(x=>x.id===id);if(!m)return;if(state.records.some(r=>r.owner===id)||state.transactions.some(t=>t.owner===id)){toast('Không thể xóa thành viên đang có hồ sơ hoặc giao dịch.');return;}if(!confirm('Xóa thành viên '+m.name+'?'))return;state.members=state.members.filter(x=>x.id!==id);await persist();closeModal();render();toast('Đã xóa thành viên.');}
async function deleteCategory(s){const [kind,group,id]=s.split('|');const groups=kind==='record'?state.categories.records:state.categories.transactions;const cat=groups[group]?.find(c=>c.id===id);if(!cat)return;const inUse=kind==='record'?state.records.some(x=>x.module===group&&x.typeId===id):state.transactions.some(x=>x.type===group&&x.categoryId===id);if(inUse){toast('Loại này đang có dữ liệu. Không thể xóa.');return;}if(groups[group].length<=1){toast('Mỗi nhóm cần có ít nhất một loại.');return;}if(!confirm('Xóa loại “'+cat.name+'”?'))return;groups[group]=groups[group].filter(c=>c.id!==id);await persist();openModal('categories',kind);render();toast('Đã xóa loại hồ sơ.');}
async function createBackup(){const rows=await dbAll('files'),keys=await dbEntries('files');const files=rows.map((f,i)=>({id:keys[i],iv:f.iv,data:b64(f.data)}));const pack={format:'HOSONHAMINH_ENCRYPTED_BACKUP',version:1,exportedAt:new Date().toISOString(),vault:vaultMeta,files};saveBlob(new Blob([JSON.stringify(pack)],{type:'application/octet-stream'}),'HoSoNhaMinh_'+today()+'.hsgd');toast('Đã tạo file sao lưu mã hóa. Hãy cất ở nơi an toàn.');}
function validateBackup(pack){if(!pack||pack.format!=='HOSONHAMINH_ENCRYPTED_BACKUP'||pack.version!==1||typeof pack.vault?.salt!=='string'||typeof pack.vault?.cipher?.iv!=='string'||typeof pack.vault?.cipher?.data!=='string'||!Array.isArray(pack.files)||pack.files.length>10000)throw new Error('File này không phải sao lưu hợp lệ của ứng dụng.');if(pack.files.some(f=>!f||typeof f.id!=='string'||typeof f.iv!=='string'||typeof f.data!=='string'))throw new Error('Dữ liệu tệp không hợp lệ.');if(pack.vault.iterations!==PBKDF2_ITERATIONS)throw new Error('Phiên bản mã hóa chưa được hỗ trợ.');}
async function restoreBackup(pack,password){validateBackup(pack);const key=await deriveKey(password,unb64(pack.vault.salt));const v=await decryptVault(pack.vault.cipher,key);const files=pack.files.map(f=>({id:f.id,iv:f.iv,data:unb64(f.data).buffer}));await dbReplaceAll(pack.vault,files);vaultMeta=pack.vault;vaultKey=key;state=v;activeView='home';}
async function changePassword(oldPass,newPass){const oldKey=await deriveKey(oldPass,unb64(vaultMeta.salt));await decryptVault(vaultMeta.cipher,oldKey);const salt=crypto.getRandomValues(new Uint8Array(16)),newKey=await deriveKey(newPass,salt);const rows=await dbAll('files'),keys=await dbEntries('files');const newFiles=[];for(let i=0;i<rows.length;i++){const bytes=await decryptBytes(rows[i],vaultKey),box=await encryptBytes(bytes,newKey);newFiles.push({id:keys[i],...box});}const newMeta={schema:1,salt:b64(salt),iterations:PBKDF2_ITERATIONS,createdAt:vaultMeta.createdAt,updatedAt:new Date().toISOString(),cipher:await encryptVault(state,newKey)};await dbReplaceAll(newMeta,newFiles);vaultMeta=newMeta;vaultKey=newKey;}
function exportFinanceCsv(){const header=['Ngày','Loại','Hạng mục','Số tiền VND','Thành viên','Hình thức','Ghi chú'];const rows=[header,...state.transactions.sort((a,b)=>b.date.localeCompare(a.date)).map(t=>[t.date,t.type==='income'?'Thu':'Chi',typeBy(state.categories.transactions[t.type],t.categoryId),t.amount,ownerName(t.owner),t.payment,t.note])];const csv='\ufeff'+rows.map(row=>row.map(value=>'"'+String(value??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');saveBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),'ThuChiGiaDinh_'+today()+'.csv');toast('Đã xuất bảng thu chi CSV (không mã hóa).');}

async function handleAction(action){switch(action){case 'sync-drive':openSync();break;case 'new-record':openModal('new-record');break;case 'new-member':openModal('new-member');break;case 'new-income':openModal('new-tx',null,'income');break;case 'new-expense':openModal('new-tx',null,'expense');break;case 'go-records':activeRecordTab='all';recordOwnerFilter='all';navigate('records');break;case 'category-records':openModal('categories','record');break;case 'category-transactions':openModal('categories','transaction');break;case 'close-modal':closeModal();break;case 'backup':await createBackup();break;case 'restore':$('#backupFile').value='';$('#backupFile').click();break;case 'change-password':openModal('change-password');break;case 'export-csv':exportFinanceCsv();break;case 'lock':lockApp();break;default:break;}}
let actionBusy=false;
document.addEventListener('click',async ev=>{
  if(!state)return;
  const t=ev.target.closest('button,[data-record],[data-open-member],[data-open-tx]');if(!t)return;
  try{
    if(t.hasAttribute('data-nav')){navigate(t.dataset.nav);return;}
    if(t.hasAttribute('data-record-tab')){activeRecordTab=t.dataset.recordTab;render();filterRecordsUI();return;}
    if(t.hasAttribute('data-tx-tab')){activeTxTab=t.dataset.txTab;render();return;}
    if(t.hasAttribute('data-cat-go')){activeRecordTab=t.dataset.catGo;recordOwnerFilter='all';navigate('records');filterRecordsUI();return;}
    if(t.hasAttribute('data-record')){openModal('view-record',t.dataset.record);return;}
    if(t.hasAttribute('data-open-member')){openModal('view-member',t.dataset.openMember);return;}
    if(t.hasAttribute('data-open-tx')){openModal('view-tx',t.dataset.openTx);return;}
    if(t.hasAttribute('data-edit-record')){openModal('edit-record',t.dataset.editRecord);return;}
    if(t.hasAttribute('data-edit-member')){openModal('edit-member',t.dataset.editMember);return;}
    if(t.hasAttribute('data-edit-tx')){openModal('edit-tx',t.dataset.editTx);return;}
    if(t.hasAttribute('data-member-records')){recordOwnerFilter=t.dataset.memberRecords;activeRecordTab='all';closeModal();navigate('records');filterRecordsUI();return;}
    if(t.hasAttribute('data-attachment-remove')){if(activeEdit?.remove){activeEdit.remove.add(t.dataset.attachmentRemove);t.closest('.attachment-row').classList.add('hidden');}return;}
    if(t.hasAttribute('data-preview')){await previewAttachment(t.dataset.preview);return;}
    if(t.hasAttribute('data-download')){await downloadAttachment(t.dataset.download);return;}
    if(t.hasAttribute('data-cat-edit')){const [kind,group,id]=t.dataset.catEdit.split('|');openModal('category-form',kind,{group,catId:id});return;}
    if(t.hasAttribute('data-cat-add')){openModal('category-form',t.dataset.catAdd);return;}
    if(t.hasAttribute('data-cat-back')){openModal('categories',t.dataset.catBack);return;}
    if(actionBusy)return;
    actionBusy=true;
    if(t.hasAttribute('data-delete-record'))await deleteRecord(t.dataset.deleteRecord);
    else if(t.hasAttribute('data-delete-tx'))await deleteTx(t.dataset.deleteTx);
    else if(t.hasAttribute('data-delete-member'))await deleteMember(t.dataset.deleteMember);
    else if(t.hasAttribute('data-cat-delete'))await deleteCategory(t.dataset.catDelete);
    else if(t.dataset.action)await handleAction(t.dataset.action);
  }catch(e){console.error(e);toast('Có lỗi: '+e.message);}finally{actionBusy=false;}
});
document.addEventListener('keydown',e=>{if(!state)return;if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-record],[data-open-member],[data-open-tx]')){e.preventDefault();e.target.click();}});
document.addEventListener('input',e=>{if(!state)return;if(e.target.id==='recordSearch'){searchTerm=e.target.value;filterRecordsUI();}});
document.addEventListener('change',e=>{if(!state)return;const t=e.target;if(t.id==='recordOwner'){recordOwnerFilter=t.value;filterRecordsUI();}if(t.id==='recordOrder')filterRecordsUI();if(t.id==='financeMonth'){activeMonth=t.value||monthNow();render();}if(t.name==='module'&&t.closest('#editorForm')&&activeEdit?.kind==='record'){const pick=$('#f_typeId');pick.innerHTML=categoryOptions(state.categories.records[t.value],state.categories.records[t.value]?.[0]?.id);refreshRecordFields();}if(t.name==='typeId'&&t.closest('#editorForm')&&activeEdit?.kind==='record'){refreshRecordFields();}if(t.name==='type'&&t.closest('#editorForm')){const pick=$('#f_categoryId');pick.innerHTML=categoryOptions(state.categories.transactions[t.value],state.categories.transactions[t.value]?.[0]?.id);}});
$('#topLock').addEventListener('click',()=>lockApp());
$('#fab').addEventListener('click',()=>{if(state)openModal('quick-add');});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});
document.addEventListener('submit',async e=>{if(!['authForm','editorForm'].includes(e.target.id))return;e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit]');if(button.disabled)return;button.disabled=true;const oldLabel=button.textContent;button.textContent='Đang xử lý...';try{if(form.id==='authForm'){const pass=$('#authPassword').value;if(form.dataset.mode==='create'){if(pass.length<8)throw new Error('Mật khẩu cần ít nhất 8 ký tự.');if(pass!==$('#authConfirm').value)throw new Error('Hai mật khẩu không khớp.');await beginVault(pass);}else await unlock(pass);}else await saveEditor(form);}catch(err){console.error(err);if(form.id==='authForm')authError(form.dataset.mode==='unlock'?(err.hsgdAuthCode?err.message:'HS00 – Lỗi mở ứng dụng. Không xóa kho dữ liệu.'):err.message);else toast('Chưa thể lưu: '+err.message);}finally{if(button.isConnected){button.disabled=false;button.textContent=oldLabel;}}});
document.addEventListener('click',async e=>{const id=e.target.id;if(id==='authShowPass'){const p=$('#authPassword');p.type=p.type==='password'?'text':'password';e.target.textContent=p.type==='text'?'Ẩn mật khẩu':'Hiện mật khẩu';return;}if(id!=='authRescue'||e.target.disabled)return;const btn=e.target,out=$('#authRescueStatus');btn.disabled=true;try{await exportLockedBackup();out.textContent='Đã yêu cầu tải bản sao mã hóa. Giữ file riêng, không đưa lên GitHub.';}catch(err){out.textContent='Chưa sao lưu được. Không xóa dữ liệu trình duyệt.';}finally{btn.disabled=false;}});
$('#backupFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>150*1024*1024)throw new Error('File sao lưu quá lớn để mở trên thiết bị này.');const pack=JSON.parse(await file.text());validateBackup(pack);backupPending=pack;openModal('restore');}catch(err){toast('Không đọc được sao lưu: '+err.message);}});
for(const n of ['pointerdown','keydown','touchstart'])document.addEventListener(n,()=>{if(state)lastActive=Date.now();},{passive:true});
setInterval(()=>{if(state&&Date.now()-lastActive>IDLE_LOCK_MS){lockApp();toast('Đã tự khóa để bảo vệ dữ liệu.');}},30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state&&Date.now()-lastActive>IDLE_LOCK_MS){lockApp();toast('Đã tự khóa để bảo vệ dữ liệu.');}});
window.addEventListener('error',e=>console.error('Ứng dụng:',e.message));
async function init(){try{if(!window.isSecureContext||!crypto?.subtle){$('#authContent').innerHTML=`<div class="auth-panel"><h2>Yêu cầu kết nối an toàn</h2><p>Hãy mở ứng dụng qua địa chỉ HTTPS (chẳng hạn GitHub Pages) hoặc localhost để sử dụng mã hóa và lưu hồ sơ an toàn.</p></div>`;return;}if(!window.indexedDB)throw new Error('Trình duyệt không hỗ trợ lưu hồ sơ.');db=await idbOpen();vaultMeta=await dbGet('meta','vault');renderAuth(!vaultMeta);if('serviceWorker'in navigator&&location.protocol==='https:'){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(e=>console.warn('Không thể cài offline:',e));}}catch(e){console.error(e);$('#authContent').innerHTML=`<div class="auth-panel"><h2>Chưa thể khởi động</h2><p>${esc(e.message)}. Hãy kiểm tra chế độ riêng tư và dung lượng bộ nhớ của trình duyệt.</p></div>`;}}
init();
